export const SectionHeading = ({ title, isFirst = false }) => {
  const isLaptopNarrow = useMediaQuery(ROUTING_LAPTOP_NARROW_MQ);
  return (
    <div
      style={{
        margin: isFirst
          ? isLaptopNarrow
            ? "16px 0 24px 0"
            : "0 0 24px 0"
          : "16px 0 24px 0",
        position: "relative",
      }}
    >
      <div style={{ borderTop: `1px solid ${C.divider}` }} />
      <span
        style={{
          position: "absolute",
          top: -10,
          left: 0,
          background: C.cardBg,
          paddingRight: 8,
          fontSize: 13,
          fontWeight: 500,
          color: C.labelText,
          letterSpacing: "0.01em",
        }}
      >
