export const StorageFieldRow = ({
  label,
  tooltip,
  required = false,
  labelColWidth = STORAGE_LABEL_COL_WIDTH,
  controlColWidth = STORAGE_CONTROL_COL_WIDTH,
  fieldColGap = STORAGE_FIELD_COL_GAP,
  children,
}) => {
  const labelNode = (
    <label
      style={{
        fontSize: 12,
        color: C.labelText,
        fontWeight: 600,
        width: "100%",
        minWidth: 0,
        lineHeight: 1.35,
        wordBreak: "break-word",
        cursor: tooltip ? "help" : "default",
      }}
    >
      {label}
      {required && <span style={{ color: C.errorRed }}> *</span>}
    </label>
  );

  const labelWrapStyle = {
    flex: `0 0 ${labelColWidth}px`,
    width: labelColWidth,
    maxWidth: labelColWidth,
    minWidth: labelColWidth,
  };

  const valueColStyle = {
    flex: "1 1 auto",
    minWidth: controlColWidth,
    display: "flex",
    flexDirection: "column",
    alignItems: "flex-end",
    justifyContent: "flex-start",
    paddingTop: 2,
  };

  const controlSlotStyle = {
    display: "flex",
    flexDirection: "column",
    alignItems: "flex-start",
    width: controlColWidth,
    minWidth: controlColWidth,
    maxWidth: controlColWidth,
  };

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "row",
        alignItems: "flex-start",
        width: "100%",
        minHeight: 36,
        gap: fieldColGap,
      }}
    >
      {label ? (
        <div style={labelWrapStyle}>
          {tooltip ? (
            <Tooltip title={tooltip} {...tooltipProps}>
              {labelNode}
            </Tooltip>
          ) : (
            labelNode
          )}
        </div>
      ) : null}

      <div style={valueColStyle}>
        <div style={controlSlotStyle}>{children}</div>
      </div>
    </div>
  );
};

const renderTextField = (value, onChange, type = "text", max = null) => (
  <TextField
    type={type}
    value={value}
    onChange={(e) => {
      const val = e.target.value;

      if (max === null || val === "" || Number(val) <= max) {
        onChange(val);
      }
    }}
    size="small"
    fullWidth
    variant="outlined"
    inputProps={{
      min: 0,
      max,
      style: {
        fontSize: 13,
        height: 32,
        padding: "0 8px",
        boxSizing: "border-box",
      },
    }}
    sx={modalTextFieldSx}
  />
);

const renderSelect = (value, onChange, options) => (
  <Select
    value={value}
    onChange={(e) => onChange(e.target.value)}
    size="small"
    fullWidth
    variant="outlined"
    sx={modalSelectSx}
  >
    {options.map((opt) => (
      <MenuItem key={opt} value={opt} sx={{ fontSize: 13 }}>
        {opt}
      </MenuItem>
    ))}
  </Select>
);

const renderRadio = (value, onChange, options) => (
  <RadioGroup row value={value} onChange={(e) => onChange(e.target.value)}>
    {options.map((opt) => (
      <FormControlLabel
        key={opt}
        value={opt}
        control={
          <Radio
            size="small"
            sx={{
              color: OUTLINED_BORDER,
              "&.Mui-checked": { color: OUTLINED_FOCUS },
            }}
          />
        }
        label={opt}
        sx={{
          "& .MuiFormControlLabel-label": {
            fontSize: 13,
            color: C.labelText,
          },
        }}
      />
    ))}
  </RadioGroup>
);

export const StorageFormField = ({
  field,
  form,
  onChange,
  errors = {},
  labelColWidth = STORAGE_LABEL_COL_WIDTH,
  controlColWidth = STORAGE_CONTROL_COL_WIDTH,
  fieldColGap = STORAGE_FIELD_COL_GAP,
}) => {
  const value = form[field.name] ?? "";
  const fieldRowProps = {
    labelColWidth,
    controlColWidth,
    fieldColGap,
  };

  if (field.name === "startHour" || field.name === "startMinute") {
    return (
      <StorageFieldRow
        key={field.name}
        label={field.name === "startMinute" ? "" : field.label}
        required
        {...fieldRowProps}
      >
        <div style={{ width: "100%" }}>
          {renderSelect(value, (v) => onChange(field.name, v), field.options)}
        </div>
      </StorageFieldRow>
    );
  }

  return (
    <StorageFieldRow
      key={field.name}
      label={field.label}
      tooltip={field.tooltip}
      required
      {...fieldRowProps}
    >
      {field.type === "select"
        ? renderSelect(value, (v) => onChange(field.name, v), field.options)
        : field.type === "radio"
          ? renderRadio(value, (v) => onChange(field.name, v), field.options)
          : (
            <div style={{ position: "relative", width: "100%" }}>
              {errors[field.name] && (
                <div
                  style={{
                    position: "absolute",
                    top: -18,
                    left: 0,
                    color: C.errorRed,
                    fontSize: 11,
                  }}
                >
                  {errors[field.name]}
                </div>
              )}

              {renderTextField(
                value,
                (v) => onChange(field.name, v),
                field.type,
                field.max,
              )}
            </div>
          )}
    </StorageFieldRow>
  );
};

